import{_ as a,c as t,o,ag as r}from"./chunks/framework.Sr95JMjc.js";const h=JSON.parse('{"title":"여러가지 AI 모델을 사용하려고 할 때","description":"","frontmatter":{"title":"여러가지 AI 모델을 사용하려고 할 때","date":"2025-11-28T23:00+09:00","tags":["GPT","Claude","Gemini"]},"headers":[],"relativePath":"posts/ai-apis.md","filePath":"posts/ai-apis.md","lastUpdated":1777592848000}'),i={name:"posts/ai-apis.md"};function n(l,e,s,p,m,d){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="여러가지-ai-모델을-사용하려고-할-때" tabindex="-1">여러가지 AI 모델을 사용하려고 할 때 <a class="header-anchor" href="#여러가지-ai-모델을-사용하려고-할-때" aria-label="Permalink to &quot;여러가지 AI 모델을 사용하려고 할 때&quot;">​</a></h1><p>OpenAI, Claude, Gemini 에서 제공하는 API를 통해서 AI 분석 요청을 하는 코드를 보고 오래된 모델 이외에 최신 모델들을 추가해보고 있어요. 대부분 하위 호환성을 지원하지 않고 사용하고자 하는 모델마다 요청 시 전달해야하는 파라미터 옵션이 달라지기 때문에 사용할 수 없는 파라미터가 포함되는 요청은 오류가 발생할 수 있으므로 주의해야해요.</p><h2 id="model-id" tabindex="-1">Model ID <a class="header-anchor" href="#model-id" aria-label="Permalink to &quot;Model ID&quot;">​</a></h2><p>모델 ID는 대부분 별칭으로 정의한 Stable 과 날짜를 포함한 Snapshot 버전이 있는데 제미나이의 경우에는 정식 버전과 프리뷰 버전으로 나누어져 있어요.</p><ul><li>gpt-5.1: <a href="https://platform.openai.com/docs/models/gpt-5.1" target="_blank" rel="noreferrer">gpt-5.1-2025-11-13</a></li><li>claude-opus-4-5: <a href="https://platform.claude.com/docs/en/about-claude/models/overview#latest-models-comparison" target="_blank" rel="noreferrer">claude-opus-4-5-20251101</a></li><li><a href="https://ai.google.dev/gemini-api/docs/models#gemini-3-pro" target="_blank" rel="noreferrer">gemini-3-pro-preview</a></li></ul><p>그리고 Gemini API 는 Model ID를 <code>model</code> 파라미터가 아닌 <a href="https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash" target="_blank" rel="noreferrer">API URL에 포함</a>하고 있어요.</p><h2 id="api-key" tabindex="-1">API Key <a class="header-anchor" href="#api-key" aria-label="Permalink to &quot;API Key&quot;">​</a></h2><p>API 인증을 위한 키는 커스텀 헤더 또는 Authorization 헤더로 전달해야해요.</p><ul><li>OpenAI: <code>Authorization</code> Header (Bearer Token)</li><li>Claude: <code>X-Api-Key</code> Header</li><li>Gemini: <code>x-goog-api-key</code> Header</li></ul><h2 id="system-instruction" tabindex="-1">System Instruction <a class="header-anchor" href="#system-instruction" aria-label="Permalink to &quot;System Instruction&quot;">​</a></h2><p>시스템 안내사항을 전달하여 AI 모델의 역할이나 답변 스타일 등을 정의할 수 있어요. 다만, 이 시스템 안내사항을 전달할 수 있는 방법은 AI 마다 다릅니다.</p><ul><li>OpenAI : <a href="https://platform.openai.com/docs/guides/prompt-engineering#message-roles-and-instruction-following" target="_blank" rel="noreferrer">Message roles and instruction following</a></li><li>Claude : <a href="https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/system-prompts" target="_blank" rel="noreferrer">Giving Claude a role with a system prompt</a></li><li>Gemini : <a href="https://ai.google.dev/gemini-api/docs/text-generation#system-instructions" target="_blank" rel="noreferrer">System instructions and other configurations</a></li></ul><p>시스템 프롬프트(지침)를 사용하면 전체 토큰 수가 늘어나지만 서비스에 맞는 AI 에이전트를 만들어서 제공할 수 있어요.</p><h2 id="temperature" tabindex="-1">temperature <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;temperature&quot;">​</a></h2><blockquote><p>For Gemini 3, we strongly recommend keeping the temperature parameter at its default value of 1.0.</p></blockquote><p>Gemini 3 모델들은 추론 능력이 기본적으로 최적화 되어있는 상태라 temperature 파라미터를 설정하는 것을 권장하지 않는다고 하니까 파라미터를 사용하지 않거나 1.0 으로 고정하는게 좋습니다.</p><h2 id="max-tokens-→-max-completion-tokens" tabindex="-1">max_tokens → max_completion_tokens <a class="header-anchor" href="#max-tokens-→-max-completion-tokens" aria-label="Permalink to &quot;max_tokens → max_completion_tokens&quot;">​</a></h2><p>OpenAI는 원래 <a href="https://platform.openai.com/docs/api-reference/chat/create#chat_create-max_tokens" target="_blank" rel="noreferrer">max_tokens</a> 파라미터를 사용해서 응답에서 생성할 수 있는 토큰의 최대 길이를 제한할 수 있었어요. max_tokens 파라미터는 Deprecated 되어있는 상태로 GPT-5 모델들을 사용하고자 하는경우 <mark>max_completion_tokens</mark> 를 사용해야 오류가 발생하지 않아요.</p><ul><li>OpenAI: max_tokens or max_completion_tokens</li><li>Claude: max_tokens</li><li>Gemini: GenerationConfig.max_output_tokens</li></ul><h2 id="official-sdk" tabindex="-1">Official SDK <a class="header-anchor" href="#official-sdk" aria-label="Permalink to &quot;Official SDK&quot;">​</a></h2><p>회사 프로젝트에는 REST API 를 직접 사용하는 것으로 코드가 구현되어있는데 각 Claude, Gemini, OpenAI 에서 공식적으로 제공하는 SDK 를 사용하는 것이 좋아보여요.</p><ul><li>OpenAI: <a href="https://github.com/openai/openai-java" target="_blank" rel="noreferrer">openai/openai-java</a></li><li>Gemini: <a href="https://github.com/googleapis/java-genai" target="_blank" rel="noreferrer">googleapis/java-genai</a></li><li>Claude: <a href="https://github.com/anthropics/anthropic-sdk-java" target="_blank" rel="noreferrer">anthropics/anthropic-sdk-java</a></li></ul>',22)])])}const u=a(i,[["render",n]]);export{h as __pageData,u as default};
